local SlackTubMaker = {}
local PRODUCTS = {
    iron_slacktub = { name = "Železni kad za ohlajanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni kad za ohlajanje za kovace." },
    bronze_slacktub = { name = "Bronast kad za ohlajanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast kad za ohlajanje za kovace." },
    silver_slacktub = { name = "Srebrn kad za ohlajanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn kad za ohlajanje za kovace." },
    gilded_slacktub = { name = "Pozlačen kad za ohlajanje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen kad za ohlajanje za kovace." },
    jewel_set_slacktub = { name = "Draguljast kad za ohlajanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast kad za ohlajanje za kovace." },
    royal_sovereign_slacktub = { name = "Kraljevski suveren kad za ohlajanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren kad za ohlajanje z biseri za krono." },
}
local BUILDINGS = {
    slacktub_workshop = { name = "Slacktub delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    slacktub_house = { name = "Slacktub hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_slacktub_atelier = { name = "Mojstrski slacktub atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_slacktub_palace = { name = "Suverena slacktub palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SlackTubMaker.ironStock = 12; SlackTubMaker.bronzeStock = 10; SlackTubMaker.woodStock = 16; SlackTubMaker.leatherStock = 12; SlackTubMaker.silverStock = 8; SlackTubMaker.goldStock = 6; SlackTubMaker.jewelStock = 4; SlackTubMaker.pearlStock = 4
SlackTubMaker.productStock = {}; SlackTubMaker.buildings = {}; SlackTubMaker.maker = nil; SlackTubMaker.activeMaking = {}; SlackTubMaker.totalProducts = 0; SlackTubMaker.dayTimer = 0
function SlackTubMaker.init() SlackTubMaker.ironStock=12; SlackTubMaker.bronzeStock=10; SlackTubMaker.woodStock=16; SlackTubMaker.leatherStock=12; SlackTubMaker.silverStock=8; SlackTubMaker.goldStock=6; SlackTubMaker.jewelStock=4; SlackTubMaker.pearlStock=4; SlackTubMaker.productStock={}; SlackTubMaker.buildings={}; SlackTubMaker.maker=nil; SlackTubMaker.activeMaking={}; SlackTubMaker.totalProducts=0; SlackTubMaker.dayTimer=0; print("[SlackTubMaker] Royal Slack Tub Maker System initialized (6 products, 4 buildings)") end
function SlackTubMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SlackTubMaker.maker={name=n or ("Ohlajevalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ohlajevalec najet: %s (spretnost: %d)",SlackTubMaker.maker.name,s),"success") end; return true end
function SlackTubMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SlackTubMaker.build(id) local ok,e=SlackTubMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SlackTubMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SlackTubMaker.getQualityBonus() local b=0; for _,bd in ipairs(SlackTubMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SlackTubMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SlackTubMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SlackTubMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SlackTubMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SlackTubMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SlackTubMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SlackTubMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SlackTubMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SlackTubMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SlackTubMaker.buildings==0 then return false,"Potrebna ohlajevalna delavnica" end; if not SlackTubMaker.maker then return false,"Potreben ohlajevalec" end; return true end
function SlackTubMaker.make(pt,qty) qty=qty or 1; local ok,e=SlackTubMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SlackTubMaker.ironStock=SlackTubMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SlackTubMaker.bronzeStock=SlackTubMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SlackTubMaker.woodStock=SlackTubMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SlackTubMaker.leatherStock=SlackTubMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SlackTubMaker.silverStock=SlackTubMaker.silverStock-d.silverCost*qty end; if d.goldCost then SlackTubMaker.goldStock=SlackTubMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SlackTubMaker.jewelStock=SlackTubMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SlackTubMaker.pearlStock=SlackTubMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SlackTubMaker.maker then t=math.max(1,t-math.floor(SlackTubMaker.maker.skill/13)) end; table.insert(SlackTubMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SlackTubMaker.completeMaking(m) local q=1.0+(SlackTubMaker.getQualityBonus()/100); if SlackTubMaker.maker then q=q+(SlackTubMaker.maker.skill/140) end; q=math.min(2.5,q); SlackTubMaker.productStock[m.productType]=(SlackTubMaker.productStock[m.productType] or 0)+m.quantity; SlackTubMaker.totalProducts=SlackTubMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SlackTubMaker.maker then SlackTubMaker.maker.itemsMade=SlackTubMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SlackTubMaker.maker.skill=math.min(100,SlackTubMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kad izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function SlackTubMaker.update(dt) if not _G.state then return end; SlackTubMaker.dayTimer=SlackTubMaker.dayTimer+dt; if SlackTubMaker.dayTimer>=30 then SlackTubMaker.dayTimer=0; for i=#SlackTubMaker.activeMaking,1,-1 do local m=SlackTubMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SlackTubMaker.completeMaking(m); table.remove(SlackTubMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SlackTubMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SlackTubMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SlackTubMaker.getStats() return {ironStock=SlackTubMaker.ironStock,bronzeStock=SlackTubMaker.bronzeStock,woodStock=SlackTubMaker.woodStock,leatherStock=SlackTubMaker.leatherStock,silverStock=SlackTubMaker.silverStock,goldStock=SlackTubMaker.goldStock,jewelStock=SlackTubMaker.jewelStock,pearlStock=SlackTubMaker.pearlStock,productStock=SlackTubMaker.productStock,numBuildings=#SlackTubMaker.buildings,hasMaker=SlackTubMaker.maker~=nil,makerName=SlackTubMaker.maker and SlackTubMaker.maker.name or "—",makerSkill=SlackTubMaker.maker and SlackTubMaker.maker.skill or 0,activeMaking=#SlackTubMaker.activeMaking,totalProducts=SlackTubMaker.totalProducts} end
return SlackTubMaker
